try:
    role = self.iam_backend.get_role_by_arn(pipeline["roleArn"])
    policy_doc = json.loads(role.assume_role_policy_document)
    statements = policy_doc["Statement"]

    # Check all statements in the trust policy
    has_codepipeline = False
    for statement in statements:
        if statement.get("Effect") == "Allow" and "Principal" in statement and "Service" in statement["Principal"]:
            service_principal = statement["Principal"]["Service"]

            # Handle both string and list service principals
            if isinstance(service_principal, str):
                if service_principal == "codepipeline.amazonaws.com":
                    has_codepipeline = True
                    break
            elif isinstance(service_principal, list):
                if "codepipeline.amazonaws.com" in service_principal:
                    has_codepipeline = True
                    break

    if not has_codepipeline:
        raise IAMNotFoundException("")
except IAMNotFoundException:
    raise InvalidStructureException(
        f"CodePipeline is not authorized to perform AssumeRole on role {pipeline['roleArn']}"
    )
